using System;using System.IO;using System.Linq;using System.Security.Cryptography;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class B3RepairSession {
 static string H=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B3_StructureRepair/"));
 public static object Begin(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||!s.path.EndsWith("/Player.unity"))throw new Exception("Player edit scene required");bool dirty=s.isDirty;File.Copy(s.path,H+"player_disk_before.unity",true);if(dirty&&!EditorSceneManager.SaveScene(s))throw new Exception("Player save failed");var protect=Directory.GetFiles(Application.dataPath,"*",SearchOption.AllDirectories).Where(p=>p.EndsWith(".cs")||p.EndsWith(".unity")||p.Contains("07.Animator")||p.Contains("04.Prefabs")).ToDictionary(p=>p.Replace('\\','/'),p=>BitConverter.ToString(SHA256.Create().ComputeHash(File.ReadAllBytes(p))));File.WriteAllText(H+"protected_session.json",JsonConvert.SerializeObject(protect,Formatting.Indented));File.WriteAllText(H+"return_scene.txt",s.path);EditorSceneManager.OpenScene("Assets/Afrer_Seconds/01.Scenes/Stage/Level_B3_Circular.unity");return new{savedPlayer=dirty,protectedFiles=protect.Count,active=SceneManager.GetActiveScene().path};}
 public static object End(){if(Application.isPlaying)throw new Exception("Exit Play first");var s=SceneManager.GetActiveScene();if(s.isDirty)throw new Exception("Save B3 explicitly first");EditorSceneManager.OpenScene(File.ReadAllText(H+"return_scene.txt"));var before=JsonConvert.DeserializeObject<System.Collections.Generic.Dictionary<string,string>>(File.ReadAllText(H+"protected_session.json"));var changed=before.Where(p=>!File.Exists(p.Key)||BitConverter.ToString(SHA256.Create().ComputeHash(File.ReadAllBytes(p.Key)))!=p.Value).Select(p=>p.Key).ToArray();File.WriteAllText(H+"protected_result.json",JsonConvert.SerializeObject(new{count=before.Count,changed},Formatting.Indented));return new{active=SceneManager.GetActiveScene().path,dirty=SceneManager.GetActiveScene().isDirty,changed};}
}
